package com.wangzan101.mika.core.tool

import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive

/**
 * Tool names from before the rename → the current names, generated by rule from the registered tools (no hand-written mapping table):
 * a capability's tool name is `<capability>_<rest>`; a verb present on several screens used to have a single unprefixed name (`tap`), and now has one per screen;
 * when only one screen has it, the former name is the old prefix of that capability in [formerPrefix] plus the rest (the phone has no prefix, `launch_app`; the web uses `browser_`);
 * rest parts that also changed are listed in [renamed] (current name → former name);
 * [retired] holds old names that were removed without a replacement tool (old name → how to do it now), and is rewritten into that wording.
 * [moved] holds names that do not follow the rules above and were renamed wholesale (old name → current name; a name split into several has several).
 *
 * Used only to read old material: stored experience routes, how run records are displayed, personal skills and practices loaded into context, and the hint when the model calls an old name.
 * Calling a tool by its old name is never silently swapped for the new name and executed.
 */
class LegacyNames(
    private val index: ToolIndex,
    formerPrefix: Map<String, String>,
    renamed: Map<String, String> = emptyMap(),
    private val retired: Map<String, String> = emptyMap(),
    moved: Map<String, List<String>> = emptyMap(),
) {
    private val table: Map<String, List<String>>

    init {
        val infos = index.names.mapNotNull { index[it] }
        val out = LinkedHashMap<String, MutableList<String>>()
        for (t in infos) {
            // Newer phone commands have no unprefixed historical name.
            if (t.verb in setOf(Verb.Query, Verb.Collect, Verb.PhoneRun, Verb.PhoneFind, Verb.PhoneExtract,
                    Verb.PhoneDialog, Verb.PhoneEvent, Verb.PhoneGesture, Verb.PhoneCommand)) continue
            val cap = t.capability ?: continue
            val prefix = formerPrefix[cap] ?: continue
            if (!t.name.startsWith("${cap}_")) continue
            val rest = t.name.removePrefix("${cap}_")
            // Another screen has the same verb with the same rest part: this used to be one shared name without a prefix
            val shared = infos.any { o -> o !== t && o.capability != cap && o.capability in formerPrefix && o.verb == t.verb && o.name == "${o.capability}_$rest" }
            val old = renamed[t.name] ?: if (shared) rest else prefix + rest
            if (old != t.name && old !in index.names) out.getOrPut(old) { mutableListOf() } += t.name
        }
        for ((old, news) in moved) news.filter { it in index.names }.takeIf { it.isNotEmpty() }?.let { out.getOrPut(old) { mutableListOf() } += it }
        table = out
    }

    /** Current names for an old name (several for a verb that exists on multiple screens); empty when it is not an old name. */
    fun replacements(old: String): List<String> =
        table[old].orEmpty()

    /**
     * The new names to suggest when the model calls the old name [old]: for a name split into knowledge and skill, pick the matching one by the kind argument (or the `kind:` prefix of name),
     * and give both when it cannot be told.
     */
    fun replacements(old: String, args: JsonObject): List<String> {
        val all = replacements(old)
        if (all.size < 2) return all
        val kind = args.text("kind") ?: args.text("name")?.substringBefore(':', "")
        val verbs = when (kind) {
            "app", "site" -> setOf(Verb.KnowledgeSearch, Verb.KnowledgeRead)
            "skill", "personal" -> setOf(Verb.SkillSearch, Verb.SkillRead)
            else -> return all
        }
        return all.filter { index.verb(it) in verbs }.ifEmpty { all }
    }

    private fun JsonObject.text(key: String): String? = (this[key] as? JsonPrimitive)?.takeIf { it.isString }?.content

    /** How to do it now for an old name that was removed without a replacement tool; null when it is not such an old name. */
    fun retiredAs(old: String): String? = retired[old]

    /** The old names, each registered by name. */
    val names: Set<String> get() = table.keys

    /** The new name for an old name that passes [accept] (for example, only those that can be stored into routes); null when it is not an old name or none fits. */
    fun resolve(old: String, accept: (String) -> Boolean = { true }): String? = replacements(old).firstOrNull(accept)

    /**
     * Old tool names mentioned in text are replaced with the current ones: old names containing an underscore (`launch_app`, `browser_navigate`) are replaced anywhere;
     * ones that are plain English words (`tap`, `back`) are replaced only inside backticks. A name shared by several screens is written as "`phone_tap` / `web_tap`".
     */
    fun rewrite(text: String): String = renamedIn(retiredIn(text))

    /**
     * A removed old name is replaced with the sentence describing what to do now, together with the preceding "call" action, which is replaced as well: inside backticks it is replaced anywhere;
     * without backticks (it may be a plain English word) it is replaced only where it is a tool name: right after "call", or wedged between Chinese characters.
     */
    private fun retiredIn(text: String): String {
        var out = text
        for ((old, instead) in retired) {
            val name = Regex.escape(old)
            out = Regex("(?:(?i:call)\\s+|调用\\s*)?`$name`").replace(out, instead)
            out = Regex("(?:(?i:call)\\s+|调用\\s*)(?<![A-Za-z0-9_])$name(?![A-Za-z0-9_])").replace(out, instead)
            out = Regex("(?<=[\\u4e00-\\u9fff])\\s*$name(?![A-Za-z0-9_])|(?<![A-Za-z0-9_])$name\\s*(?=[\\u4e00-\\u9fff])").replace(out) { " $instead " }
        }
        return out
    }

    private fun renamedIn(text: String): String {
        if (table.isEmpty()) return text
        fun joined(news: List<String>, tick: Boolean): String {
            fun t(s: String) = if (tick) "`$s`" else s
            return news.joinToString(" / ") { t(it) }
        }
        val ticked = TICKED.replace(text) { m -> replacements(m.groupValues[1]).takeIf { it.isNotEmpty() }?.let { joined(it, true) } ?: m.value }
        return WORD.replace(ticked) { m ->
            val w = m.value
            if ('_' !in w) w else replacements(w).takeIf { it.isNotEmpty() }?.let { joined(it, false) } ?: w
        }
    }

    private companion object {
        val TICKED = Regex("`([a-z][a-z0-9_]*)`")
        val WORD = Regex("(?<![A-Za-z0-9_`])[a-z][a-z0-9]*(?:_[a-z0-9]+)+(?![A-Za-z0-9_`])")
    }
}
